#include "route_recovery.h"
#include <algorithm>
namespace puyo {
const char* routeRecoveryStatusName(RouteRecoveryStatus status) { switch(status){ case RouteRecoveryStatus::None:return "NONE"; case RouteRecoveryStatus::Connected:return "CONNECTED"; case RouteRecoveryStatus::Weak:return "WEAK"; case RouteRecoveryStatus::Stale:return "STALE"; case RouteRecoveryStatus::Abandon:return "ABANDON"; } return "NONE"; }
RouteRecoveryState analyzeRouteRecovery(int routeLength,int trueTriggerPath,int safeMoves,int previousSafeMoves,int bestNextSafeMoves,int previousBestNextSafeMoves,int inheritedStaleAge,int productiveNextMoves,int productiveFollowupMoves,int bestImmediateNetClear,int bestRebuildChain,int bestRebuildNetClear,int bestRebuildNextSafeMoves,int maxHeight,bool rebuildPolicy){
 RouteRecoveryState out; const bool measured=safeMoves>=0; const bool connected=routeLength>=6&&trueTriggerPath>=2; const bool weak=routeLength>=6&&trueTriggerPath==1; const bool stale=measured&&safeMoves<=5&&routeLength>=6&&trueTriggerPath<=0; out.stale=stale; out.staleAge=stale?std::min(8,std::max(0,inheritedStaleAge)+1):0; if(stale&&out.staleAge>=3)out.status=RouteRecoveryStatus::Abandon; else if(stale)out.status=RouteRecoveryStatus::Stale; else if(connected)out.status=RouteRecoveryStatus::Connected; else if(weak)out.status=RouteRecoveryStatus::Weak; else if(rebuildPolicy&&measured&&trueTriggerPath>0)out.status=RouteRecoveryStatus::Connected; if(previousSafeMoves>=0&&measured)out.deltaSafeMoves=safeMoves-previousSafeMoves; if(previousBestNextSafeMoves>=0&&bestNextSafeMoves>=0)out.deltaBestNextSafeMoves=bestNextSafeMoves-previousBestNextSafeMoves; double score=0.0; if(out.deltaSafeMoves>0)score+=out.deltaSafeMoves*26000.0; else if(out.deltaSafeMoves<0)score+=out.deltaSafeMoves*6000.0; if(out.deltaBestNextSafeMoves>0)score+=out.deltaBestNextSafeMoves*10000.0; else if(out.deltaBestNextSafeMoves<0)score+=out.deltaBestNextSafeMoves*4000.0; score+=std::max(0,trueTriggerPath)*12000.0; score+=std::max(0,productiveNextMoves)*5500.0; score+=std::max(0,productiveFollowupMoves)*4000.0; score+=std::max(0,bestImmediateNetClear)*1800.0; score+=std::max(0,bestRebuildChain)*9000.0; score+=std::max(0,bestRebuildNetClear)*2500.0; if(bestRebuildNextSafeMoves>0)score+=bestRebuildNextSafeMoves*3000.0; if(measured&&safeMoves>=6)score+=std::min(safeMoves-5,5)*1400.0; score-=std::max(0,maxHeight-10)*4500.0; if(stale)score-=out.staleAge*15000.0; if(out.status==RouteRecoveryStatus::Abandon)score-=30000.0; out.score=std::clamp(score,-90000.0,120000.0); return out; }
} // namespace puyo
